import openpyxl, os

wb = openpyxl.load_workbook(os.environ['OUT_XLSX'])
ws = wb['Sheet2']

bad = {'-', '0', '$', '$0', '$0.0'}

def is_bad(v):
    if v is None:
        return True
    if isinstance(v, str):
        s = v.strip()
        if s == '':
            return True
        if s in bad:
            return True
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if v == 0:
            return True
    return False

# Collect kept rows (data rows only, row 2 onward)
kept_rows = []
for r in range(2, ws.max_row + 1):
    j = ws.cell(r, 10).value
    k = ws.cell(r, 11).value
    if not (is_bad(j) and is_bad(k)):
        row_data = [ws.cell(r, c).value for c in range(1, 12)]
        kept_rows.append(row_data)

# Write kept rows back starting at row 2
for i, row_data in enumerate(kept_rows):
    r = i + 2
    for c in range(1, 12):
        ws.cell(r, c).value = row_data[c - 1]

# Clear trailing rows beyond the new data
new_last = len(kept_rows) + 1  # header + data rows
for r in range(new_last + 1, ws.max_row + 1):
    for c in range(1, 12):
        ws.cell(r, c).value = None

wb.save(os.environ['OUT_XLSX'])
print(f'Kept {len(kept_rows)} data rows, new last row = {new_last}')
